621817368.en:
ok adding this:
```rust
ty::InstanceKind::Shim(ty::ShimKind::DropGlue(_, ty)) => {
                    if let Some(ty) = ty {
                        match ty.kind() {
                            TyKind::CoroutineClosure(def_id, _) => *def_id,
                            TyKind::Coroutine(def_id, _) => *def_id,
                            _ => return None,
                        }
                    } else {
                        return None;
                    }
                }
```
invalidates only 1 CGU when changing the string constant, and brings down the incremental recompile of bors (with debug=0) from 14s to 8s (!!!)

