Or rather, a (userspace) primitive which I'll call `io_write_sync` is roughly equivalent to:
```rust
fn io_write_sync(target: IoHandle, bytes: &[u8]) {
     let done = AtomicBool::new(false);
     std::thread::spawn( || { os_do_write(target, bytes); done = true; }); 
     while !done.load(Ordering::Acquire) {
          if env.wants_termination() { exit() }
          spin_loop_hint();
     }
}
```

